-- Unreal B.S. -> Power BI star schema export. Run after build_mart (mart.* tables).
\set d '/home/claude/unreal-bs/powerbi/data'
-- ===== Dimensions =====
\copy (select d::date as date, date_trunc('month',d)::date as month_start, extract(year from d)::int as year, extract(month from d)::int as month_num, to_char(d,'Mon YYYY') as month_label, to_char(d,'YYYY-MM') as year_month, 'Q'||extract(quarter from d)::int||' '||extract(year from d)::int as quarter_label, to_char(d,'Dy') as weekday, (extract(isodow from d) < 6) as is_weekday, (d = (date_trunc('month',d)+interval '1 month -1 day')::date) as is_month_end from generate_series('2024-10-01'::timestamp,'2026-10-31'::timestamp,'1 day') d order by 1) to 'data/dim_date.csv' csv header
\copy (with mk as (select distinct on (customer_id) customer_id, market from mart.arr_snapshot_monthly order by customer_id, snapshot_month), first_arr as (select customer_id, min(snapshot_month) as first_arr_month from mart.arr_snapshot_monthly group by 1) select c.id as customer_id, c.name as customer_name, upper(c.currency) as currency, coalesce(mk.market, case upper(c.currency) when 'USD' then 'US' when 'GBP' then 'UK' else 'Eurozone' end) as market, c.address_country as country, c.created::date as created_date, fa.first_arr_month, (c.id like 'cus_STORY%') as is_story_customer from stripe.customer c left join mk on mk.customer_id=c.id left join first_arr fa on fa.customer_id=c.id where not c.is_deleted order by 1) to 'data/dim_customer.csv' csv header
\copy (select a.id as account_id, a.account_number, a.name as account_name, a.classification, a.account_type, case when a.classification in ('Revenue','Expense') then 'P&L' else 'Balance sheet' end as statement, m."#" as walk_order, m."Walk" as walk, m."Waterfall step" as walk_step, m."Relationship to ARR" as relationship_to_arr from quickbooks.account a left join mart.account_map m on m."GL account"=a.name order by a.account_number) to 'data/dim_gl_account.csv' csv header
\copy (select distinct check_order, check_name, account as gl_account from mart.recon_status_monthly order by 1) to 'data/dim_recon_check.csv' csv header
\copy (select distinct on (rc_id) rc_id, category, title, from_date, to_date, what_happened, prevention, status, correction_memo, dr_account, cr_account from mart.root_cause_register order by rc_id) to 'data/dim_root_cause.csv' csv header
\copy (select rc_id, check_name from mart.root_cause_register order by 1,2) to 'data/bridge_root_cause_check.csv' csv header
\copy (select distinct walk*10+step_order as step_key, walk, step_order, step from mart.arr_to_cash_detail order by 1) to 'data/dim_walk_step.csv' csv header
-- ===== Facts =====
\copy (select snapshot_month, subscription_id, customer_id, plan, billing_interval, upper(currency) as currency, round(arr_local,6) as arr_local, round(fx_rate,6) as fx_rate_to_usd, round(arr_usd,6) as arr_usd, round(mrr_usd,6) as mrr_usd from mart.arr_snapshot_monthly order by 1,3) to 'data/fact_arr_snapshot.csv' csv header
\copy (select snapshot_month, customer_id, movement_type, round(opening_usd,6) as opening_arr_usd, round(movement_usd,6) as movement_usd, round(fx_usd,6) as fx_usd, round(closing_usd,6) as closing_arr_usd from mart.arr_movements_monthly order by 1,2) to 'data/fact_arr_movement.csv' csv header
\copy (select txn_date, check_name, round(stripe_usd,2) as stripe_usd, round(books_usd,2) as books_usd, round(diff_usd,2) as diff_usd, ties from mart.recon_daily order by 1, check_order) to 'data/fact_recon_daily.csv' csv header
\copy (select month||'|'||check_name as month_check_key, month, check_name, round(diff_usd,2) as diff_usd, status, nullif(rc_ids,'') as rc_ids from mart.recon_status_monthly order by 1, check_order) to 'data/fact_recon_monthly.csv' csv header
\copy (select r.month||'|'||r.check_name as month_check_key, r.month, r.check_name, trim(x) as rc_id from mart.recon_status_monthly r cross join lateral unnest(string_to_array(r.rc_ids, ',')) x where coalesce(r.rc_ids,'')<>'' order by 1,2,3) to 'data/bridge_recon_month_root_cause.csv' csv header
\copy (select rc_id, txn_date, check_name, round(stripe_usd,2) as stripe_usd, round(books_usd,2) as books_usd, round(diff_usd,2) as diff_usd, evidence from mart.recon_exceptions order by 1,2) to 'data/fact_recon_exception.csv' csv header
\copy (select row_number() over (order by entry_date, rc_id, debit_usd desc nulls last) as line_id, rc_id, entry_date, memo, account as account_name, round(debit_usd,2) as debit_usd, round(credit_usd,2) as credit_usd from mart.correcting_entries order by 1) to 'data/fact_correcting_entry.csv' csv header
\copy (select month, walk*10+step_order as step_key, gl_account, recon_check, row_type, nullif(customer_id,'') as customer_id, source_id, round(amount_usd,6) as amount_usd, reason, calculation, nullif(rc_id,'') as rc_id from mart.arr_to_cash_detail order by 1,2) to 'data/fact_walk_line.csv' csv header
\copy (select je.transaction_date as posting_date, 'Journal entry' as source, je.doc_number, l.journal_entry_id as source_id, l.index as line_index, l.account_id, l.posting_type, round(case when l.posting_type='Debit' then l.amount else -l.amount end,2) as signed_amount_usd, l.description from quickbooks.journal_entry_line l join quickbooks.journal_entry je on je.id=l.journal_entry_id where not je._fivetran_deleted union all select d.transaction_date, 'Deposit', d.private_note, d.id, -1, d.account_id, 'Debit', round(d.total_amount,2), 'Bank deposit' from quickbooks.deposit d where not d._fivetran_deleted union all select d.transaction_date, 'Deposit', d.private_note, d.id, dl.index, dl.deposit_account_id, 'Credit', round(-dl.amount,2), dl.description from quickbooks.deposit_line dl join quickbooks.deposit d on d.id=dl.deposit_id where not d._fivetran_deleted order by 1,4,5) to 'data/fact_gl_line.csv' csv header
